            concrete_cases.append({'case_id': case_id, 'query': query, 'gold_ids': [gold_id], 'distractor_ids': distractor_ids, 'category': f"distractor_{template['type']}", 'notes': f"Evaluation case for type {template['type']}"})
            case_counter += 1
