def generate_filler_memories(count, existing_count):
    fillers = []
    types_list = ['fact', 'preference', 'decision', 'pattern', 'context', 'lesson']
    classes = ['short', 'medium']
    for i in range(count):
        m_id = f'mem_filler_{existing_count + i:05d}'
        proj = f'filler-project-{random.randint(1, 200)}'
        tech = random.choice(TECHNOLOGIES)
        port = random.choice(PORTS)
        file_name = random.choice(FILES)
        val = random.choice(VALUES)
        m_type = random.choice(types_list)
        l_class = random.choice(classes)
        type_temps = [t for t in SEED_TEMPLATES if t['type'] == m_type and t['length_class'] == l_class]
        if not type_temps:
            type_temps = [t for t in SEED_TEMPLATES if t['type'] == m_type]
        template = random.choice(type_temps)
        content = template['content'].format(project=proj, tech=tech, port=port, file=file_name, value=val)
        fillers.append({'id': m_id, 'type': m_type, 'scope': 'private', 'project': proj, 'tags': template['tags'], 'content': content, 'length_class': l_class})
    return fillers
fillers_1500 = generate_filler_memories(1500, 500)
